CREATE TABLE capability_aliases (alias VARCHAR(120) PRIMARY KEY, canonical_id VARCHAR(120) NOT NULL, revision VARCHAR(80) NOT NULL, FOREIGN KEY(canonical_id) REFERENCES capability_identities(id));
